create table public.trips (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,title text not null check(char_length(title) between 1 and 500),status text not null default 'dream' check(status in('dream','shortlist','planning','booked','completed','archived')),destination_label text,country_code text,region text,description text,start_date date,end_date date,budget_cny numeric(12,2) check(budget_cny is null or budget_cny>=0),cover_image_url text,notes_markdown text not null default '',created_via text not null default 'manual' check(created_via in('manual','command_palette','assistant','import')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),completed_at timestamptz,archived_at timestamptz);
create table public.trip_stops (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,trip_id uuid not null references public.trips(id) on delete cascade,day_number integer check(day_number is null or day_number>0),sort_order integer not null default 0,place_name text not null check(char_length(place_name) between 1 and 500),address text,latitude double precision check(latitude is null or latitude between -90 and 90),longitude double precision check(longitude is null or longitude between -180 and 180),planned_time time,duration_minutes integer check(duration_minutes is null or duration_minutes>0),notes text,geocode_status text not null default 'unresolved' check(geocode_status in('unresolved','resolved','failed')),geocode_provider text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index trips_user_status_idx on public.trips(user_id,status); create index trip_stops_trip_sort_idx on public.trip_stops(trip_id,sort_order);
create trigger trips_updated_at before update on public.trips for each row execute procedure public.set_updated_at(); create trigger trip_stops_updated_at before update on public.trip_stops for each row execute procedure public.set_updated_at();
alter table public.trips enable row level security; alter table public.trip_stops enable row level security;
create policy "trips_own" on public.trips for all using((select auth.uid())=user_id) with check((select auth.uid())=user_id);
create policy "trip_stops_own" on public.trip_stops for all using((select auth.uid())=user_id and exists(select 1 from public.trips where id=trip_id and user_id=(select auth.uid()))) with check((select auth.uid())=user_id and exists(select 1 from public.trips where id=trip_id and user_id=(select auth.uid())));
revoke all on public.trips,public.trip_stops from anon; grant select,insert,update,delete on public.trips,public.trip_stops to authenticated;
